function guidesForTool(tool:Tool){return guides.filter(guide=>guide.tool===tool.route||tools.find(candidate=>candidate.route===guide.tool)?.category===tool.category||(guide.href==='/guides/profit-margin-vs-markup'&&['/calculators/markup-calculator','/calculators/selling-price-calculator'].includes(tool.route)))}
function slugOf(path:string){return path.split('/').filter(Boolean).at(-1)||''}
function routeUrl(path:string){return `${site}${path}`}
export async function generateStaticParams(){return [...tools.map(t=>({slug:t.route.split('/').filter(Boolean)})),...guides.map(g=>({slug:g.href.split('/').filter(Boolean)})),...['tools','calculators','pricing-calculators','freelancer-tools','business-documents','marketing-tools','video-tools','website-tools','pdf-tools','image-tools','guides','about','contact','privacy','terms','disclaimer'].map(s=>({slug:[s]}))]}
export async function generateMetadata({params}:{params:Promise<{slug:string[]}>}):Promise<Metadata>{const {slug}=await params;const path='/'+slug.join('/');const key=slugOf(path);const t=tools.find(x=>x.route===path);const g=guides.find(x=>x.href===path);const category=fileCategories[key];const collection=collectionMetadata[key];const page=pageCopy[key];const isUtmPage=path==='/marketing-tools/utm-builder';const utmTitle='Free UTM Link Builder for Google Analytics 4 | Digitalivez Tools';const utmDescription='Create free UTM links for Google Analytics 4. Add campaign source, medium and name, preview your tracking URL and copy it instantly. No signup required.';const seoOverrides:Record<string,{title:string;description:string;image?:string}>={'/image-tools/image-resizer':{title:'Free Passport Photo Resizer – Passport Size & 1×1 Photo | Digitalivez',description:'Resize a photo to passport size or 1×1 square dimensions online for free. Preview and download locally in your browser. Check your country’s passport photo requirements.'},'/video-tools/video-trimmer':{title:'Free Online Video Trimmer – Cut MP4, MOV & WebM | Digitalivez',description:'Trim videos online for free. Cut supported MP4, MOV and WebM clips, preview your selection and download the result. Processing happens in your browser.'},'/guides/business-break-even-point':{title:'Break-Even Point Formula: How to Calculate Units & Sales | Digitalivez',description:'Learn how to calculate your business break-even point using simple formulas and examples. Find your break-even units, sales revenue and target profit.'},'/guides/profit-margin-vs-markup':{title:'Profit Margin vs. Markup: Formulas, Differences & Examples | Digitalivez',description:'Understand the difference between profit margin and markup with simple formulas, practical pricing examples and a guide to calculating both correctly.'},'/business-documents/invoice-generator':{title:'Free Invoice Generator – Create & Save Invoices | Digitalivez Tools',description:'Create professional invoices online for free. Add business and customer details, products, quantities, taxes and discounts, then generate a printable invoice.'},'/business-documents':{title:'Free Business Document Generators – Invoices, Quotations & More | Digitalivez',description:'Create professional business documents online with free invoice, quotation and receipt generators. Simple tools for freelancers and small businesses.'},'/image-upscaler':{title:'AI Image Upscaler Online – 2× & 4× | Digitalivez',description:'Upscale JPG, PNG, WebP, and supported AVIF images with a real AI super-resolution model in your browser. Compare and download the result.',image:'/og-image-ai-upscaler.png'},'/video-upscaler':{title:'Video Upscaler Online for PC – 2× & 4× | Digitalivez',description:'Upscale compatible videos 2× or 4× in a desktop browser. Process frames locally, preserve supported audio, and download the result. PC only; no mobile support.',image:'/og-image-video-upscaler.png'}};const seo=seoOverrides[path];const pageTitle=t?.title||g?.title||category?.title||collection?.title||page?.title.replace(/ Digitalivez Tools$/,'')||'Digitalivez Tools';const title:Metadata['title']=isUtmPage?{absolute:utmTitle}:seo?{absolute:seo.title}:pageTitle;const description=isUtmPage?utmDescription:seo?.description||t?.meta||g?.description||category?.description||collection?.description||page?.intro||'Free, practical browser-based business tools from Digitalivez Tools.';const fullTitle=isUtmPage?utmTitle:seo?.title||`${pageTitle} | Digitalivez`;return{title,description,alternates:{canonical:routeUrl(path)},openGraph:{title:fullTitle,description,url:routeUrl(path),siteName:'Digitalivez Tools',type:g?'article':'website',images:[{url:seo?.image||'/og-image.png',width:1424,height:752,alt:`${pageTitle} — Digitalivez Tools`}]},twitter:{card:'summary_large_image',title:fullTitle,description,images:[seo?.image||'/og-image.png']},robots:isUtmPage||path==='/image-upscaler'||path==='/video-upscaler'?{index:true,follow:true}:undefined}}
function Crumbs({items}:{items:{label:string;href?:string}[]}){const nodes=[{label:'Home',href:'/'},...items].map((item,index)=>({type:'ListItem',position:index+1,name:item.label,item:item.href?routeUrl(item.href):undefined}));return <><nav className="breadcrumbs" aria-label="Breadcrumb"><Link href="/">Home</Link>{items.map((item,index)=><span key={index} className="crumb-item"><ChevronRight size={14}/>{item.href?<Link href={item.href}>{item.label}</Link>:<span aria-current="page">{item.label}</span>}</span>)}</nav><script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:nodes}).replace(/</g,'\\u003c')}}/></>}
function FileCategoryCards(){return <div className="file-category-cards"><Link href="/pdf-tools" className="file-category-card"><span className="file-category-icon"><FileText size={21}/></span><span className="eyebrow">{tools.filter(tool=>tool.category==='PDF Tools').length} BROWSER TOOLS</span><h2>PDF Tools</h2><p>Merge, split, convert, rotate, number, and watermark documents locally.</p><span className="card-link">Explore PDF tools <ArrowUpRight size={15}/></span></Link><Link href="/image-tools" className="file-category-card"><span className="file-category-icon"><ImageIcon size={21}/></span><span className="eyebrow">{tools.filter(tool=>tool.category==='Image Tools').length} BROWSER TOOLS</span><h2>Image Tools</h2><p>Compress, resize, convert, crop, and prepare images for social media.</p><span className="card-link">Explore image tools <ArrowUpRight size={15}/></span></Link></div>}
function FileCategoryDetails({category}:{category:NonNullable<typeof fileCategories[string]>}){return <section className="file-category-details"><div><span className="eyebrow">SUPPORTED FORMATS</span><h2>Work with common files</h2><p>{category.formats}</p></div><div><span className="eyebrow">PRIVATE BY DESIGN</span><h2>Files stay in your browser</h2><p>Your files are processed directly in your browser. They are not uploaded to Digitalivez servers.</p></div><div className="file-category-faq"><span className="eyebrow">FREQUENTLY ASKED QUESTIONS</span><h2>Before you start</h2><FAQAccordion items={category.faq}/><p>Looking for a different file workflow? <Link href={category.category==='PDF Tools'?'/image-tools':'/pdf-tools'}>{category.category==='PDF Tools'?'Browse Image Tools':'Browse PDF Tools'}</Link>.</p></div></section>}
function CollectionPage({title,description,items,category,collectionKey}:{title:string;description:string;items:typeof tools;category?:keyof typeof fileCategories;collectionKey:string}){const explicitGuides=(collectionRelatedGuideRoutes[collectionKey]||[]).map(href=>guides.find(guide=>guide.href===href)).filter((guide):guide is (typeof guides)[number]=>Boolean(guide));const matchingGuides=guides.filter(guide=>items.some(item=>item.route===guide.tool||tools.find(candidate=>candidate.route===guide.tool)?.category===item.category));const relevantGuides=[...new Map([...explicitGuides,...matchingGuides].map(guide=>[guide.href,guide])).values()].slice(0,4);const relatedTools=(collectionRelatedToolRoutes[collectionKey]||[]).map(route=>tools.find(item=>item.route===route)).filter((item):item is Tool=>Boolean(item));return <><Crumbs items={[{label:title}]}/><div className="collection-head"><span className="eyebrow">DIGITALIVEZ TOOLKIT</span><h1>{collectionKey==='business-documents'?'Free Business Document Generators':title}</h1><p>{description}</p></div>{collectionIntros[collectionKey]&&<p className="collection-context">{collectionIntros[collectionKey]}</p>}{title==='All tools'&&<FileCategoryCards/>}<div className="tool-grid collection-grid">{items.map((tool,index)=><Link href={tool.route} className="tool-card" key={tool.route}><div className={`tool-icon color-${index%4}`}>{collectionKey==='business-documents'?tool.route.endsWith('invoice-generator')?<FileText size={19}/>:tool.route.endsWith('quotation-generator')?<ClipboardList size={19}/>:<Receipt size={19}/>:<CheckCircle2 size={19}/>}</div><span className="tool-category">{tool.category}</span><h2>{tool.name}</h2><p>{tool.description}</p><span className="card-link">Use this tool <ArrowUpRight size={15}/></span></Link>)}</div>{collectionKey==='business-documents'&&<section className="prose-block document-category-guide"><span className="eyebrow">DOCUMENT BASICS</span><h2>Essential Business Documents for Small Businesses</h2><p>An invoice requests payment for products or services supplied. A quotation describes proposed work and pricing before it is accepted. A receipt confirms that a payment has been received. Use the document that matches the stage of the transaction and check local requirements.</p><h2>Why Use Online Business Document Generators?</h2><p>Online generators make routine documents easier to prepare, help keep formatting consistent, and reduce repeated setup. Review names, dates, amounts, and terms before sharing; the tools do not determine tax or legal obligations.</p><h2>Frequently Asked Questions</h2><FAQAccordion items={businessDocumentCategoryFaqs}/></section>}{category&&<FileCategoryDetails category={fileCategories[category]}/>}<section className="supporting"><h2>Related guides</h2><div className="related-links">{relevantGuides.map(guide=><Link key={guide.href} href={guide.href}>{guide.title}<ArrowRight size={15}/></Link>)}</div></section>{relatedTools.length>0&&<section className="supporting"><h2>Related tools</h2><div className="related-links">{relatedTools.map(item=><Link key={item.route} href={item.route}>{item.name}<ArrowRight size={15}/></Link>)}</div></section>}</>}

