function ToolSchema({tool}:{tool:Tool}){const applicationCategory=tool.category==='PDF Tools'||tool.category==='Image Tools'?'MultimediaApplication':tool.category==='Profitability Calculators'||tool.category==='Pricing Calculators'?'FinanceApplication':tool.category==='Business Documents'?'BusinessApplication':'UtilitiesApplication';const schema={'@context':'https://schema.org','@type':'WebApplication',name:tool.name,description:tool.description,url:routeUrl(tool.route),applicationCategory,operatingSystem:'Any',offers:{'@type':'Offer',price:'0',priceCurrency:'USD'}};return <script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify(schema).replace(/</g,'\\u003c')}}/>}
function FileToolPage({tool}:{tool:Tool}){
 const categoryHref=tool.category==='PDF Tools'?'/pdf-tools':'/image-tools'
 const related=tools.filter(item=>item.category===tool.category&&item.route!==tool.route).slice(0,4)
 const steps=fileToolSteps[tool.route.split('/').filter(Boolean).at(-1)||'']||[]
 const formats=tool.category==='PDF Tools'?(tool.route.endsWith('/jpg-to-pdf')?'JPG, JPEG, PNG → PDF':'PDF'):tool.route.endsWith('/image-to-base64')?'JPG, PNG, WebP, AVIF, Base64':tool.route.endsWith('/favicon-generator')?'JPG, PNG, WebP, AVIF where browser-supported':tool.route.endsWith('/image-compressor')?'JPG, PNG, and WebP input · JPG and WebP output':'JPG, JPEG, PNG, WebP, AVIF where browser-supported'
 const localPrivacy='Your files are processed directly in your browser. They are not uploaded to Digitalivez servers.'
 const compression=tool.route.endsWith('/compress-pdf')
 const fileFaqs=[{question:'Are my files uploaded?',answer:localPrivacy},{question:'Can I preview the output before downloading?',answer:'Yes. Select Preview result to create and display the processed output. Download controls appear with the preview only after processing succeeds.'},...(compression?[{question:'Will the compressed PDF keep selectable text?',answer:'No. This image-based compression renders each page as a JPEG, so text is not selectable or searchable. The original file is not changed.'}]:[])]
 const relatedGuides=guidesForTool(tool).slice(0,4)
 return <><Header/><main className="inner-main"><Crumbs items={[{label:tool.category,href:categoryHref},{label:tool.name}]}/><ToolSchema tool={tool}/><header className="tool-page-head"><span className="eyebrow">{tool.category.toUpperCase()} · FREE BROWSER TOOL</span><h1>{tool.name}</h1><p>{tool.description} Preview the actual result before downloading. Files stay on your device.</p></header><div className="tool-layout file-tool-layout"><div className="file-tool-main">{tool.route==='/pdf-tools/pdf-editor'?<PdfEditor/>:<ToolWorkspace tool={tool}/>}<section className="prose-block file-tool-guide"><span className="eyebrow">HOW TO USE THIS TOOL</span><h2>{tool.name}: steps and details</h2><ol>{steps.map(step=><li key={step}>{step}</li>)}</ol><h3>How it works</h3><p>{tool.description} Processing uses browser APIs and runs locally on your device. The tool creates an actual output file, displays that output for inspection, and waits for you to download it.</p><h3>Supported formats</h3><p>{formats}</p><h3>Privacy</h3><p>{localPrivacy}</p>{compression&&<><h3>Compression limitation</h3><p>This browser-only compression method renders each page to a quality-controlled JPEG and rebuilds the PDF. It can reduce image-heavy files, but it rasterizes page content, so text is no longer selectable or searchable. Already optimized PDFs may not become smaller.</p></>}</section>{tool.route==='/image-tools/image-resizer'&&<section className="prose-block file-tool-guide passport-photo-guide"><span className="eyebrow">PASSPORT PHOTO RESIZER</span><h2>Resize a passport photo online</h2><p>Use the quick size presets above to create a square image for passport or ID photo applications. The preset provides a convenient pixel size, but passport photo rules are different around the world. Confirm the required printed dimensions, resolution, background, framing, and file type with the issuing authority before submitting.</p><h3>Passport photo size and 1×1 photo</h3><p>The passport preset creates a 600 × 600 pixel square image, while the 1×1 preset creates a 300 × 300 pixel image. Both are square; pixels alone do not guarantee a specific printed size or satisfy official photo rules. For a print-ready photo, check the required pixels per inch (PPI) and physical dimensions.</p><h3>How to make a passport-size picture</h3><ol><li>Choose your photo and select the passport-size or 1×1 quick preset.</li><li>Check that the image meets the destination country or organization’s photo rules.</li><li>Preview the resized image and download it when it looks right.</li></ol><p>Images are resized in your browser and are not uploaded to Digitalivez.</p><h3>Passport photo resizer FAQ</h3><FAQAccordion items={passportPhotoFaqs}/></section>}<section className="faq-list tool-faq"><h2>Frequently asked questions</h2><FAQAccordion items={fileFaqs}/></section><section className="supporting"><h2>Related guides</h2><div className="related-links">{relatedGuides.map(guide=><Link href={guide.href} key={guide.href}>{guide.title}<ArrowRight size={15}/></Link>)}</div></section><section className="file-related-tools"><div><span className="eyebrow">KEEP WORKING</span><h2>Related tools</h2></div><div className="related-links">{related.map(item=><Link href={item.route} key={item.route}>{item.name}<ArrowRight size={15}/></Link>)}<Link href={categoryHref}>All {tool.category.toLowerCase()}<ArrowRight size={15}/></Link></div></section></div><aside className="file-tool-aside"><div className="aside-card"><ShieldCheck size={21}/><h2>Local by design</h2><p>{localPrivacy}</p><span>Supported formats: {formats}</span></div><div className="aside-card"><span className="eyebrow">IN THIS TOOL</span><ul>{steps.map(step=><li key={step}>{step}</li>)}</ul></div></aside></div></main><Footer/></>
}

export default async function RoutePage({params}:{params:Promise<{slug:string[]}>}){const {slug}=await params;const path='/'+slug.join('/');const tool=tools.find(item=>item.route===path);const guide=guides.find(item=>item.href===path);const key=slugOf(path);let content:React.ReactNode
 if(tool?.route==='/image-tools/image-upscaler')return <ImageUpscalerPage/>;if(tool?.route==='/video-tools/video-upscaler')return <VideoUpscalerPage/>;if(tool?.category==='Video Tools')return <VideoTrimmerPage tool={tool}/>;if(tool?.category==='Website & SEO Tools')return <><Header/><main className="inner-main"><Crumbs items={[{label:'Website & SEO Tools',href:'/website-tools'},{label:tool.name}]}/><ToolSchema tool={tool}/><header className="tool-page-head"><span className="eyebrow">WEBSITE &amp; SEO TOOLS · FREE BROWSER TOOL</span><h1>{tool.name}</h1><p>{tool.description} Generated content stays in your browser.</p></header><WebsiteGenerator tool={tool}/><section className="prose-block file-tool-guide"><h2>How to use this generator</h2><p>{tool.description} Add only information you can verify, then review the generated file before publishing it. The output is produced from your entries in the browser.</p><h2>What the output does and does not do</h2><p>{tool.example} This generator does not crawl websites or guarantee search rankings, crawler behavior, AI visibility, or search rich-result eligibility. Validate the generated file against your own requirements before deployment.</p><h2>Privacy and related tools</h2><p>No submitted information is sent to Digitalivez servers. Try the <Link href="/marketing-tools/utm-builder">UTM Link Builder</Link> or browse the <Link href="/website-tools">Website &amp; SEO tools</Link> collection.</p></section></main><Footer/></>
 if(tool?.route==='/marketing-tools/qr-code-generator')return <><Header/><main className="inner-main"><Crumbs items={[{label:'Marketing tools',href:'/marketing-tools'},{label:tool.name}]}/><ToolSchema tool={tool}/><header className="tool-page-head"><span className="eyebrow">MARKETING &amp; DESIGN · FREE BROWSER TOOL</span><h1>QR Code Generator Online</h1><p>Create static QR codes for links, text, Wi-Fi, contacts, messages, phone numbers, and locations. Customize your design and download it without sending your content to a server.</p></header><QrCodeGenerator/><section className="prose-block file-tool-guide"><h2>Static QR codes, made locally</h2><p>This tool encodes the information you enter directly into a static QR code. It does not create trackable links or rely on a Digitalivez redirect service. Keep the destination or payload accurate before printing, because changing the source content requires generating a new code.</p><h2>Scan-test before sharing</h2><p>High error correction and a generous quiet zone help preserve readability, but logos, gradients, small print sizes, and low contrast can still affect scanning. When local scanning is supported, the preview reports whether the generated code resolves to the exact entered payload. Always test the downloaded file on another device before publishing it.</p><h2>Privacy</h2><p>QR content and uploaded logo images are processed in your browser only. Explore the <Link href="/marketing-tools/utm-builder">UTM Link Builder</Link> for campaign URLs, or browse all <Link href="/marketing-tools">Marketing tools</Link>.</p></section></main><Footer/></>
 if(tool&&(tool.category==='PDF Tools'||tool.category==='Image Tools'))return <FileToolPage tool={tool}/>
 if(tool){const isMarketing=tool.category==='Marketing Tools';const isDocument=tool.category==='Business Documents';const categoryHref=tool.category==='Profitability Calculators'?'/calculators':tool.category==='Pricing Calculators'?'/pricing-calculators':tool.category==='Freelancer Tools'?'/freelancer-tools':tool.category==='Business Documents'?'/business-documents':'/marketing-tools';const sameCategoryTools=tools.filter(item=>item.route!==tool.route&&item.category===tool.category).slice(0,3);const relatedRoutes=tool.route==='/calculators/profit-margin-calculator'?['/calculators/markup-calculator','/calculators/break-even-calculator']:tool.route==='/calculators/markup-calculator'?['/calculators/profit-margin-calculator','/calculators/selling-price-calculator']:tool.route==='/calculators/selling-price-calculator'?['/calculators/profit-margin-calculator','/calculators/markup-calculator']:tool.route==='/calculators/break-even-calculator'?['/calculators/profit-margin-calculator']:[];const prioritizedRelated=relatedRoutes.map(route=>tools.find(item=>item.route===route)).filter((item):item is Tool=>Boolean(item));const related=prioritizedRelated.length?prioritizedRelated:sameCategoryTools.length?sameCategoryTools:tools.filter(item=>item.route==='/image-tools/social-media-resizer'||item.route==='/image-tools/image-compressor').slice(0,3);const relatedGuides=guidesForTool(tool).slice(0,4);content=<><Crumbs items={[{label:tool.category,href:categoryHref},{label:tool.name}]}/><ToolSchema tool={tool}/><header className="tool-page-head"><span className="eyebrow">{tool.category.toUpperCase()}</span><h1>{isMarketing?'Free UTM Link Builder':tool.route==='/business-documents/invoice-generator'?'Free Online Invoice Generator':tool.name}</h1><p>{isMarketing?'Build accurate campaign tracking URLs for Google Analytics 4 (GA4) in seconds. Enter your destination URL, choose your traffic source and add campaign details. Preview your completed tracking link and copy it instantly. Everything is generated in your browser without requiring an account.':tool.route==='/business-documents/invoice-generator'?'Create a professional invoice for your business or freelance work without complicated accounting software. Add your business and customer details, line items, quantities, taxes, and discounts, then generate a printable invoice.':isDocument?'Create and print a client-ready document in your browser. Your business and customer details stay on this device.':`${tool.description} Free, instant, and calculated in your browser.`}</p></header><div className={`tool-layout ${isMarketing?'utm-tool-layout':''} ${isDocument?'document-tool-layout':''}`}><div><ToolWorkspace tool={tool}/><section className="prose-block">{isMarketing?<UtmEducationalContent/>:isDocument&&tool.route==='/business-documents/invoice-generator'?<><span className="eyebrow">DOCUMENT WORKFLOW</span><h2>How to Create an Invoice Online</h2><p>Create a professional invoice for your business or freelance work without complicated accounting software. Add your business and customer details, invoice number, issue and due dates, then enter each product or service with its quantity and unit price. Add an optional discount or tax rate, review the automatically calculated total, and preview the finished invoice before printing or saving it as a PDF. Your entries stay in this browser.</p><h2>What Is an Invoice?</h2><p>An invoice is a payment request for products or services supplied under agreed terms. It records what was provided, the amount due, and when payment is expected.</p><h2>What Should an Invoice Include?</h2><p>Include your business and customer details, a unique invoice number, issue date and due date, item descriptions, quantities and prices, applicable discounts and taxes, total due, and clear payment terms. Local rules may require additional information, so check the requirements that apply to your business.</p><h2>Invoice vs Quotation vs Receipt</h2><div className="table-scroll"><table className="comparison-table"><thead><tr><th scope="col">Document</th><th scope="col">Purpose</th><th scope="col">When it is used</th></tr></thead><tbody><tr><th scope="row">Invoice</th><td>Requests payment for supplied goods or services</td><td>After work or delivery, under the agreed terms</td></tr><tr><th scope="row">Quotation</th><td>Proposes scope and pricing</td><td>Before work begins or a purchase is agreed</td></tr><tr><th scope="row">Receipt</th><td>Confirms payment was received</td><td>After a customer has paid</td></tr></tbody></table></div><h2>Why Use a Digital Invoice Generator?</h2><p>A generator keeps routine invoice details organized, applies consistent formatting, and helps you prepare a document to share or save without building a layout from scratch. Review every figure and term before sending it.</p><h2>Frequently Asked Questions</h2><FAQAccordion items={invoiceFaqs}/></>:isDocument?<><span className="eyebrow">DOCUMENT WORKFLOW</span><h2>Prepare your {tool.name.toLowerCase()}</h2><p>{tool.description} Add accurate business, customer, and line-item details, then review the document preview before printing or saving it as a PDF. Your entries are kept in this browser.</p><h3>Check details before sharing</h3><p>Confirm names, dates, item descriptions, quantities, amounts, applicable tax, and any payment or expiry terms. Requirements vary by location and business; verify that the document suits your records and agreements.</p><h3>Print or save a copy</h3><p>Use the print control to create a paper copy or save the document as a PDF. Preview the printed layout and keep a copy in the recordkeeping system you use for your business.</p></>:<><span className="eyebrow">UNDERSTANDING THE RESULT</span><h2>How to use the {tool.name.toLowerCase()}</h2><p>{tool.description} Enter values in the same currency where relevant. The result updates as you change your inputs, so you can compare scenarios before making a decision.</p><h3>The formula</h3><div className="formula-box">{tool.formula}</div><p>Use consistent inputs and check that each value reflects the same period and business assumptions. This tool provides an estimate, not financial, tax, or legal advice.</p><h3>Worked example</h3><p>{tool.example}</p><h3>When to use it</h3><p>Use this calculation when planning prices, checking a business assumption, or discussing an estimate with a client. Review the inputs with your own records before acting. For a deeper walkthrough, see the relevant business guide below.</p></>}</section>{isMarketing?<UtmFaq/>:<section className="faq-list tool-faq"><h2>Frequently asked questions</h2><FAQAccordion items={isDocument?documentToolFaqs:calculatorToolFaqs}/></section>}</div><aside className="tool-aside"><div className="aside-card"><span className="eyebrow">KEEP LEARNING</span><h2>Related guides</h2>{relatedGuides.map(item=><Link href={item.href} key={item.href}>{item.title}<ArrowRight size={15}/></Link>)}<h2 className="eyebrow related-eyebrow">Related tools</h2>{related.map(item=><Link href={item.route} key={item.route}>{item.name}<ArrowRight size={15}/></Link>)}</div><div className="aside-note">{isMarketing?'Build and preview campaign URLs locally; no account is required.':isDocument?'Your document details stay in this browser; no account is required.':'Your numbers stay in this browser. Nothing to sign up for.'}</div></aside></div></>}
 else if(guide){const article=guideArticles[key];if(!article)notFound();const primaryGuideTool=tools.find(item=>item.route===guide.tool);const relatedGuideTools=tools.filter(item=>item.category===primaryGuideTool?.category&&item.route!==guide.tool).slice(0,3);content=<><Crumbs items={[{label:'Guides',href:'/guides'},{label:guide.title}]}/><article className="article"><span className="eyebrow">{tools.find(item=>item.route===guide.tool)?.category.toUpperCase()||'PRACTICAL GUIDE'}</span><h1>{guide.title}</h1><p className="article-intro">{guide.description}</p>{article.sections.map(section=><section key={section.heading}><h2>{section.heading}</h2>{section.paragraphs.map((paragraph,index)=><p key={index}>{paragraph.split(/(\[[^\]]+\]\([^\)]+\))/g).map((part,partIndex)=>{const match=part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);return match?<Link href={match[2]} key={partIndex}>{match[1]}</Link>:part})}</p>)}</section>)}{key==='profit-margin-vs-markup'&&<div className="table-scroll"><table className="comparison-table"><thead><tr><th scope="col">Feature</th><th scope="col">Profit Margin</th><th scope="col">Markup</th></tr></thead><tbody><tr><th scope="row">Calculation basis</th><td>Selling price</td><td>Product cost</td></tr><tr><th scope="row">Formula</th><td>Profit ÷ selling price</td><td>Profit ÷ cost</td></tr><tr><th scope="row">Purpose</th><td>Measures profitability</td><td>Helps determine pricing</td></tr><tr><th scope="row">Typical use</th><td>Financial analysis</td><td>Pricing decisions</td></tr></tbody></table></div>}<div className="article-cta"><span className="eyebrow">RELATED TOOL</span><h2>Put this guide into practice</h2><p>Put these steps into practice with the related free browser-based tool.</p><Link href={guide.tool} className="primary-button">Open related tool <ArrowRight size={16}/></Link></div><p>For high-stakes decisions, confirm your assumptions with an appropriately qualified professional.</p>{relatedGuideTools.length>0&&<section className="supporting"><h2>Related tools</h2><div className="related-links">{relatedGuideTools.map(item=><Link href={item.route} key={item.route}>{item.name}<ArrowRight size={15}/></Link>)}</div></section>}</article></>}
 else if(['tools','calculators','pricing-calculators','freelancer-tools','business-documents','marketing-tools','video-tools','website-tools','pdf-tools','image-tools'].includes(key)){const title=key==='tools'?'All tools':key==='calculators'?'Profitability calculators':key==='pricing-calculators'?'Pricing calculators':key==='freelancer-tools'?'Freelancer tools':key==='business-documents'?'Business documents':key==='marketing-tools'?'Marketing tools':key==='video-tools'?'Video tools':key==='website-tools'?'Website & SEO tools':key==='pdf-tools'?fileCategories['pdf-tools'].title:fileCategories['image-tools'].title;const category=key==='pdf-tools'?'pdf-tools':key==='image-tools'?'image-tools':undefined;const items=key==='tools'?tools:key==='calculators'?tools.filter(item=>item.category==='Profitability Calculators'):key==='pricing-calculators'?tools.filter(item=>item.category==='Pricing Calculators'):key==='freelancer-tools'?tools.filter(item=>item.category==='Freelancer Tools'):key==='business-documents'?tools.filter(item=>item.category==='Business Documents'):key==='marketing-tools'?tools.filter(item=>item.category==='Marketing Tools'):key==='video-tools'?tools.filter(item=>item.category==='Video Tools'):key==='website-tools'?tools.filter(item=>item.category==='Website & SEO Tools'):category?tools.filter(item=>item.category===fileCategories[category].category):tools;content=<CollectionPage title={title} description={category?fileCategories[category].description:collectionMetadata[key]?.description||'Free, browser-based tools to help you make everyday business decisions with more clarity.'} items={items} category={category} collectionKey={key}/>}
 else if(key==='guides'){content=<><Crumbs items={[{label:'Guides'}]}/><div className="collection-head"><span className="eyebrow">PRACTICAL BUSINESS KNOW-HOW</span><h1>Guides for clearer decisions</h1><p>Plain-English explainers for the everyday numbers behind independent business.</p></div><div className="guide-list">{guides.map(item=><Link className="guide-list-card" href={item.href} key={item.href}><div><span className="eyebrow">{tools.find(tool=>tool.route===item.tool)?.category.toUpperCase()||'PRACTICAL GUIDE'}</span><h2>{item.title}</h2><p>{item.description}</p></div><ArrowRight size={19}/></Link>)}</div></>}
 else if(pageCopy[key]){const page=pageCopy[key];content=<><Crumbs items={[{label:page.title}]}/><article className="article legal-page"><span className="eyebrow">DIGITALIVEZ TOOLS</span><h1>{page.title}</h1><p className="article-intro">{page.intro}</p>{page.body.map((paragraph,index)=><p key={index}>{key==='contact'&&index===0?<><span>Email us at </span><a href="mailto:contact@digitalivez.com">contact@digitalivez.com</a><span>.</span></>:key==='privacy'&&index===1?<><span>{paragraph.replace('See Meta’s privacy policy for how Meta handles information it receives.','')}</span><span>See </span><a href="https://www.facebook.com/privacy/policy/" target="_blank" rel="noopener noreferrer">Meta&apos;s privacy policy</a><span> for how Meta handles information it receives.</span></>:paragraph}</p>)}</article></>}
 else notFound()
 return <><Header/><main className="inner-main">{content}</main><Footer/></>
}
